<template><main class="login-page"><section class="login-card"><span class="eyebrow">WE CONNECT</span><h1>Supplier sign in</h1><p>Sign in to manage products, orders and inventory.</p><form @submit.prevent="submit"><label>Email<input v-model.trim="email" type="email" autocomplete="email" required /></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required /></label><p v-if="error" class="error">{{error}}</p><button :disabled="loading" type="submit">{{loading?"Signing in…":"Sign in"}}</button></form></section></main></template>
<script setup>
import {ref} from "vue";import {useRouter} from "vue-router";const router=useRouter(),email=ref(""),password=ref(""),loading=ref(false),error=ref("");
async function submit(){loading.value=true;error.value="";try{const r=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:email.value,password:password.value})});const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.message||"Unable to sign in.");localStorage.setItem("weconnect_token",b.token);localStorage.setItem("weconnect_user",JSON.stringify(b.user));router.replace("/products");}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<style scoped>.login-page{min-height:100vh;display:grid;place-items:center;background:#f7f5f2;padding:24px}.login-card{width:min(430px,100%);padding:32px;border:1px solid #e5dfda;border-radius:16px;background:#fff;box-shadow:0 14px 40px rgba(60,40,30,.08)}.eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;color:#d2763d}.login-card h1{margin:8px 0 6px;font:700 30px Georgia,serif;color:#44312c}.login-card form{display:grid;gap:16px;margin-top:22px}.login-card label{display:grid;gap:7px;font-size:12px;font-weight:700;color:#59443c}.login-card input{padding:12px;border:1px solid #ddd4ce;border-radius:8px}.login-card button{padding:12px;border:0;border-radius:8px;background:#684b41;color:#fff;font-weight:700}.error{color:#a8473d}</style>
